<script>
  // Board is shown from the white player's side at the top, with files reversed.
  const files = ['h','g','f','e','d','c','b','a'];
  const boardState = [
    ['','','R','K','','','N','R'],
    ['P','','P','Q','','P','P','P'],
    ['','','N','','','','',''],
    ['','','','Q','P','','',''],
    ['','B','','p','','','',''],
    ['','','','','','','',''],
    ['','','','p','p','p','p','p'],
    ['r','n','b','k','q','b','n','r']
  ];

  // Remove the duplicate queen in the top position: the queen is on d4 in this position.
  boardState[0][3] = '';
  const symbols = {
    K: '♔', Q: '♕', R: '♖', B: '♗', N: '♘', P: '♙',
    k: '♚', q: '♛', r: '♜', b: '♝', n: '♞', p: '♟'
  };
  const board = document.getElementById('board');
  let selected = null;

  // The final shown position has the white queen on d4 and a black pawn on e5.
  boardState[3][4] = 'Q';
  boardState[3][3] = '';
  boardState[4][3] = 'p';
  boardState[6][3] = '';
  const lastSquares = new Set(['3,3', '4,3']);

  function render() {
    board.innerHTML = '';
    for (let r = 0; r < 8; r++) {
      for (let c = 0; c < 8; c++) {
        const sq = document.createElement('button');
        sq.type = 'button';
        sq.className = 'square btn ' + ((r + c) % 2 === 0 ? 'light' : 'dark');
        if (lastSquares.has(`${r},${c}`)) sq.classList.add('last');
        if (selected && selected.r === r && selected.c === c) sq.classList.add('selected');

        if (c === 0) {
          const rank = document.createElement('span');
          rank.className = 'coord';
          rank.textContent = String(r + 1);
          sq.appendChild(rank);
        }
        if (r === 7) {
          const file = document.createElement('span');
          file.className = 'file';
          file.textContent = files[c];
          sq.appendChild(file);
        }
        const piece = boardState[r][c];
        if (piece) {
          const span = document.createElement('span');
          span.className = 'piece';
          span.textContent = symbols[piece];
          sq.appendChild(span);
        }
        sq.addEventListener('click', () => clickSquare(r, c));
        board.appendChild(sq);
      }
    }
  }

  function clickSquare(r, c) {
    const piece = boardState[r][c];
    if (!selected) {
      if (piece) {
        selected = {r, c};
        render();
      }
      return;
    }
    if (selected.r === r && selected.c === c) {
      selected = null;
      render();
      return;
    }
    if (piece && ((piece === piece.toUpperCase()) === (boardState[selected.r][selected.c] === boardState[selected.r][selected.c].toUpperCase()))) {
      selected = {r, c};
      render();
      return;
    }
    boardState[r][c] = boardState[selected.r][selected.c];
    boardState[selected.r][selected.c] = '';
    selected = null;
    lastSquares.clear();
    lastSquares.add(`${r},${c}`);
    lastSquares.add(`${r},${c}`);
    render();
  }
  render();
</script>
